    const pending=items.filter(entry=>!doneOf(entry)).length,completed=items.filter(doneOf).length,totalLength=operations.markingSections.reduce((sum,item)=>sum+(Number(item.lengthKm)||0),0);
    const rowsHtml=filteredItems.map(entry=>{const item=entry.item,measure=entry.kind==='brush'?`${Math.round(Number(item.area)||0).toLocaleString('fr-FR')} m²`:entry.kind==='marking'?`${(Number(item.lengthKm)||0).toLocaleString('fr-FR',{maximumFractionDigits:2})} km`:'Point GPS',statusClass=doneOf(entry)?'is-complete':'is-incomplete';return `<tr><td data-label="Type"><span class="post-type-chip terrain-type-${entry.kind}">${titleOf(entry)}</span></td><td data-label="Intervention" class="field-name-cell"><strong>${esc(nameOf(entry))}</strong><small>${esc(item.note||'Aucune consigne')}</small></td><td data-label="État"><span class="field-status ${statusClass}">${esc(statusOf(entry))}</span></td><td data-label="Responsable & date" class="field-stack"><span>${esc(item.manager||'Non attribué')}</span><small>${esc(item.deadline||item.date||'—')}</small></td><td data-label="Mesure"><span class="field-count field-count-wide">${measure}</span></td><td data-label="Actions" class="org-row-actions volunteer-actions field-actions"><button class="icon-action map-action" data-terrain-focus="${esc(item.id)}" data-terrain-kind="${entry.kind}" title="Voir sur la carte">${actionIcons.map}</button>${entry.kind==='brush'?`<button class="icon-action active-action ${item.done?'is-enabled':''}" data-terrain-action="done" data-terrain-id="${esc(item.id)}" data-terrain-kind="brush" title="Changer l’état">${actionIcons.active}</button>`:entry.kind==='marking'?`<button class="icon-action field-text-action" data-terrain-action="advance" data-terrain-id="${esc(item.id)}" data-terrain-kind="marking" title="Passer à l’état suivant">SUIV.</button>`:''}<button class="icon-action delete-action" data-terrain-action="delete" data-terrain-id="${esc(item.id)}" data-terrain-kind="${entry.kind}" title="Supprimer">${actionIcons.delete}</button></td></tr>`;}).join('');
