    byId('orgContent').innerHTML=`<p class="edition-scope-note"><strong>Catalogue matériel</strong> · Les références sont communes à toutes les éditions. Le matériel Commissaire peut être rattaché aux besoins de chaque poste.</p><div class="volunteer-overview equipment-overview"><article><b>${allItems.length}</b><span>références</span></article><article><b>${totalAvailable}</b><span>unités disponibles</span></article><article><b>${linkedToPosts}</b><span>références liées aux postes</span></article><article><b>${equipmentGroups.length}</b><span>groupes de matériel</span></article></div><div class="org-toolbar volunteer-toolbar"><input id="orgSearch" type="search" placeholder="Rechercher du matériel…" value="${esc(query)}" aria-label="Rechercher du matériel"><select id="equipmentGroupFilter" aria-label="Filtrer par groupe"><option value="">Tous les groupes</option>${equipmentGroups.map(group=>`<option ${equipmentGroupFilter===group?'selected':''}>${esc(group)}</option>`).join('')}</select><select id="orgSort" aria-label="Trier le matériel"><option value="asc">Nom A → Z</option><option value="desc" ${sort==='desc'?'selected':''}>Nom Z → A</option></select><button id="orgAdd">+ Ajouter du matériel</button></div><p class="org-result-count">${matches.length} résultat(s)</p><div class="equipment-catalog">${groupsHtml||'<p class="org-muted">Aucun matériel ne correspond à ces filtres.</p>'}</div>`;
