  function parcelPopup(p,owner){const facts=[['Propriétaire',label(owner)],['Téléphone',owner?.phone],['E-mail',owner?.email]].filter(([,value])=>value),description=p.notes||p.kind||'';return `<article class="post-popup point-popup point-popup-parcel"><header><span class="post-popup-number point-popup-icon">${navIcons.parcels}</span><div><small>PARCELLE</small><h3>${esc(p.name)}</h3></div></header><div class="post-popup-hours point-popup-facts">${facts.map(([title,value])=>`<div><span>${esc(title)}</span><strong>${esc(value)}</strong></div>`).join('')}</div>${description?`<section class="post-popup-team point-popup-description"><span>Informations</span><p>${esc(description)}</p></section>`:''}</article>`;}
  function showPoint(p,key){if(!coordinates(p))return;map.easeTo({center:[p.lng,p.lat],zoom:18,pitch:40});const html=key==='posts'?postPopup(p):pointPopup(p,key);new maplibregl.Popup({maxWidth:'390px',className:'post-popup-shell',offset:14}).setLngLat([p.lng,p.lat]).setHTML(html).addTo(map);}
  const liveClockLabel=minutes=>{const value=formatClock(minutes);return value?`${value.time}${value.dayOffset>0?' (lendemain)':''}`:'—';};
  function liveCourseRange(courses){const starts=courses.map(course=>clockMinutes(course.departureTime)).filter(Number.isFinite),ends=courses.map(course=>clockMinutes(course.departureTime)+durationMinutes(course.lastDuration)).filter(Number.isFinite);return starts.length&&ends.length?{start:Math.min(...starts),end:Math.max(...ends)}:null;}
