  async function renderLive(){
    const courses=rows('courses').filter(course=>Number.isFinite(clockMinutes(course.departureTime))&&Number.isFinite(durationMinutes(course.firstDuration))&&Number.isFinite(durationMinutes(course.lastDuration))&&durationMinutes(course.lastDuration)>=durationMinutes(course.firstDuration));
    const range=liveCourseRange(courses);
    if(!range){byId('orgContent').innerHTML='<p class="org-notice">Renseignez l’heure de départ ainsi que les temps du premier et du dernier participant sur au moins un parcours pour utiliser la simulation.</p>';return;}
    if(!Number.isFinite(liveTime))liveTime=range.start;
    liveTime=Math.max(range.start,Math.min(range.end,liveTime));
    if(!liveCourseId||!courses.some(course=>course.id===liveCourseId))liveCourseId=courses[0].id;
    const course=ref('courses',liveCourseId),geo=await getTrace(course),coords=traceCoords(geo);
    if(tab!=='live'||root.hidden)return;
    const first=runnerProgressAt(course,liveTime,'firstDuration'),last=runnerProgressAt(course,liveTime,'lastDuration');
    const candidates=rows('posts').filter(coordinates).map(post=>({post,position:routePosition(coords,post)})).filter(item=>item.position&&item.position.distanceKm<=.08&&(item.post.courseIds?.length?item.post.courseIds.includes(course.id):true));
    const nextPosts=candidates.map(({post,position})=>({post,arrival:clockMinutes(course.departureTime)+durationMinutes(course.firstDuration)*position.progress})).filter(item=>item.arrival>=liveTime&&item.arrival<=liveTime+20).sort((a,b)=>a.arrival-b.arrival);
    const runnerHtml=[['Premier',first,'firstDuration'],['Dernier',last,'lastDuration']].map(([title,runner])=>`<article class="live-runner live-${title.toLowerCase()}"><span>${title}</span><b>${liveStateLabel(runner,title.toLowerCase())}</b><small>Temps course : ${esc(course[title==='Premier'?'firstDuration':'lastDuration'])}</small></article>`).join('');
    const contacts=post=>[...new Map(rows('assignments').filter(assignment=>assignment.postId===post.id).map(assignment=>{const volunteer=ref('volunteers',assignment.volunteerId);return volunteer?[volunteer.id,volunteer]:null;}).filter(Boolean)).values()];
    const contactHtml=post=>{const people=contacts(post);if(!people.length)return '<span class="live-no-contact">Aucun commissaire affecté</span>';return people.map(person=>{const text=`Bonjour ${label(person)}, le premier concurrent du ${course.name} est estimé vers ${liveClockLabel(liveTime)} à votre poste ${post.number} · ${post.name}. Merci de vous tenir prêt.`;const links=[person.phone?`<a href="sms:${esc(person.phone.replace(/[^+\d]/g,''))}?body=${encodeURIComponent(text)}">SMS</a>`:'',person.email?`<a href="mailto:${esc(person.email)}?subject=${encodeURIComponent('Gaubre’Trail · passage imminent')}&body=${encodeURIComponent(text)}">E-mail</a>`:''].filter(Boolean).join(' ');return `<span class="live-contact"><b>${esc(label(person))}</b>${links}</span>`;}).join('');};
    byId('orgContent').innerHTML=`<section class="live-intro"><div><span class="eyebrow">SIMULATION DE COURSE</span><h1>Anticiper le premier passage.</h1><p>Le repère suit une progression régulière calculée à partir des temps du premier et du dernier. Ce n’est pas du suivi GPS réel.</p></div><button id="liveShowMap">Voir le repère sur la carte ↗</button></section><section class="live-controls"><label>Parcours<select id="liveCourse">${courses.map(item=>`<option value="${esc(item.id)}" ${item.id===course.id?'selected':''}>${esc(item.name)} · ${esc(item.distance)} km</option>`).join('')}</select></label><label class="live-time">Heure simulée <output>${liveClockLabel(liveTime)}</output><input id="liveTime" type="range" min="${range.start}" max="${range.end}" value="${liveTime}" step="1"></label><div><button id="liveStart">Début</button><button id="liveBack">− 5 min</button><button id="liveForward">+ 5 min</button><button id="liveEnd">Fin</button></div></section>${coords.length<2?'<p class="org-notice">La trace de ce parcours est absente : les alertes peuvent être listées mais le repère ne peut pas être placé sur la carte.</p>':`<section class="live-runners">${runnerHtml}</section>`}<section class="live-alerts"><header><div><span class="eyebrow">PROCHAINS PASSAGES</span><h2>Prévenir les commissaires dans les 20 minutes</h2></div><span>${nextPosts.length} poste(s)</span></header>${nextPosts.map(({post,arrival})=>`<article><time>${liveClockLabel(arrival)}</time><div><strong>${esc(post.number)} · ${esc(post.name)}</strong><small>Premier concurrent estimé dans ${Math.max(0,Math.round(arrival-liveTime))} min</small>${contactHtml(post)}</div><button data-live-post="${esc(post.id)}">Voir le poste</button></article>`).join('')||'<p class="live-empty">Aucun premier passage prévu dans les 20 prochaines minutes pour ce parcours.</p>'}</section>`;
    const update=time=>{liveTime=Math.max(range.start,Math.min(range.end,time));renderLive();renderMap();};
    byId('liveCourse').onchange=event=>{liveCourseId=event.target.value;renderLive();renderMap();};byId('liveTime').oninput=event=>update(Number(event.target.value));byId('liveStart').onclick=()=>update(range.start);byId('liveEnd').onclick=()=>update(range.end);byId('liveBack').onclick=()=>update(liveTime-5);byId('liveForward').onclick=()=>update(liveTime+5);byId('liveShowMap').onclick=()=>{visibility.set(course.id,true);close();renderMap();focusCourse(course).catch(error=>status(error.message,true));};byId('orgContent').onclick=event=>{const button=event.target.closest('[data-live-post]');if(button){const post=ref('posts',button.dataset.livePost);if(post){close();showPoint(post,'posts');}}};
  }
  function renderInventory(){const list=inventory(state,null,zone,typeFilter);byId('orgContent').innerHTML=`<p class="edition-scope-note"><strong>Besoins matériels globaux</strong> · Cette vue est commune à toutes les éditions.</p><div class="org-toolbar"><select id="inventoryZone"><option value="">Toutes les zones</option>${[...new Set(rows('equipment').map(r=>r.zone).filter(Boolean))].map(z=>`<option ${zone===z?'selected':''}>${esc(z)}</option>`).join('')}</select><select id="inventoryType"><option value="">Tous les types</option>${state.equipmentTypes.map(t=>`<option value="${esc(t.id)}" ${typeFilter===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select><button id="inventoryCSV">Exporter CSV</button><button id="inventoryPrint">Imprimer</button></div><div id="inventoryPrintArea"><h3>Besoins matériels · ${esc(zone||'Toutes zones')}</h3><table><thead><tr><th>Matériel</th><th>Quantité nécessaire</th></tr></thead><tbody>${list.map(r=>`<tr><td>${esc(r.name)}</td><td>${r.quantity}</td></tr>`).join('')}</tbody></table></div>`;byId('inventoryZone').onchange=e=>{zone=e.target.value;renderInventory();};byId('inventoryType').onchange=e=>{typeFilter=e.target.value;renderInventory();};byId('inventoryPrint').onclick=()=>window.print();byId('inventoryCSV').onclick=()=>{const cell=s=>'"'+String(s).replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';download('materiel-global.csv','\ufeff'+[['Périmètre','Zone','Matériel','Quantité'],...list.map(r=>['Global',zone||'Toutes',r.name,r.quantity])].map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8');};}
  function renderMessages(){byId('orgContent').innerHTML=`<div class="org-toolbar"><select id="messageFilter"><option value="">Tous les statuts</option>${['nouveau','lu','répondu','clôturé'].map(s=>`<option ${filter===s?'selected':''}>${s}</option>`).join('')}</select><button id="messageReload">Actualiser</button></div>${rows('messages').filter(m=>!filter||filter===m.status).map(m=>`<article class="org-conversation"><h3>${esc(name('volunteers',m.volunteerId))} · ${esc(name('posts',m.postId))}</h3><span>${esc(m.status)}</span>${m.entries.map(x=>`<p><b>${x.author==='admin'?'Organisation':'Bénévole'}</b> · ${esc(new Date(x.at).toLocaleString('fr-FR'))}<br>${esc(x.text)}</p>`).join('')}<form data-reply="${esc(m.id)}"><label>Réponse<textarea name="text" required maxlength="4000"></textarea></label><button>Répondre</button></form><button data-message="${esc(m.id)}" data-status="lu">Marquer lu</button><button data-message="${esc(m.id)}" data-status="clôturé">Clôturer</button></article>`).join('')||'<p>Aucun message pour cette sélection.</p>'}`;
    byId('messageFilter').onchange=e=>{filter=e.target.value;renderMessages();};byId('messageReload').onclick=async()=>{try{state=await repo.reload();render();}catch(e){status(e.message,true);}};
    byId('orgContent').onsubmit=async e=>{if(!e.target.dataset.reply)return;e.preventDefault();const text=new FormData(e.target).get('text').trim();if(!text)return;try{await mutate(s=>{const m=s.messages.find(m=>m.id===e.target.dataset.reply);m.entries.push({author:'admin',text,at:new Date().toISOString()});m.status='répondu';});}catch(e){status(e.message,true);}};
    byId('orgContent').onclick=async e=>{const b=e.target.closest('[data-message]');if(b)try{await mutate(s=>s.messages.find(m=>m.id===b.dataset.message).status=b.dataset.status);}catch(e){status(e.message,true);}};
  }
  function renderBackup(){byId('orgContent').innerHTML=`<p>${repo.remote?'La base partagée garde une version précédente à chaque enregistrement.':'Les données de travail restent dans ce navigateur. Exportez régulièrement une sauvegarde privée et conservez-la sur votre ordinateur. Pour publier les missions et la carte, utilisez « Exporter les données publiques », renommez le fichier public.json puis déposez-le par FTP dans carte-3d/data/. Les visiteurs ne voient que cette version publiée.'}</p><button id="backupPrivate">Exporter les données privées d’organisation</button><button id="backupPublic">Exporter les données publiques</button><label class="file-button">Restaurer une sauvegarde v1 / v2 / v3<input type="file" id="backupImport" accept=".json"></label><p>La restauration remplace les données après validation. Une sauvegarde de l’état actuel sera téléchargée avant remplacement. La sauvegarde du serveur doit aussi conserver sa configuration et sa base SQLite. Le fichier public ne contient ni téléphone, ni email, ni notes privées, ni propriétaires.</p><button id="reloadState">Recharger les données du serveur</button>`;
    try {
      if(readLocalBackup(localStorage)) {
        const recovery=document.createElement('button');
        recovery.textContent='Exporter les anciennes donn\u00e9es de ce navigateur';
        recovery.onclick=()=>{try{const backup=readLocalBackup(localStorage);if(backup)download('gaubretrail-recuperation-navigateur.json',JSON.stringify(backup.data,null,2));}catch(error){status(error.message,true);}};
        byId('orgContent').append(recovery);
      }
    } catch(error) { status(error.message,true); }
    byId('backupPrivate').onclick=()=>download(`gaubretrail-prive-${Date.now()}.json`,JSON.stringify(state,null,2));byId('backupPublic').onclick=()=>download('public.json',JSON.stringify(publicData(state),null,2));byId('reloadState').onclick=async()=>{try{state=await repo.reload();render();renderMap();status('Données rechargées.');}catch(e){status(e.message,true);}};
    byId('backupImport').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const next=repo.migrate(JSON.parse(await file.text()));validate(next);if(!confirm(`Restaurer ${next.editions.length} éditions et ${next.volunteers.length} bénévoles ? Les données actuelles seront remplacées.`))return;download(`gaubretrail-avant-restauration-${Date.now()}.json`,JSON.stringify(state));await commit(next);editionId=state.editions[0].id;updateEditionOptions();selectEdition(editionId);}catch(e){status(e.message,true);}e.target.value='';};}
  function updateCourseOptions(){const courses=rows('courses'),switcher=byId('routeSwitcher');if(!switcher)return;const selected=courses.filter(isVisible);byId('routeCount').textContent=`${selected.length} / ${courses.length} parcours`;byId('routeTitle').textContent=selected.length===1?`${Number(selected[0].distance).toLocaleString('fr-FR')} KM`:selected.length?`${selected.length} PARCOURS`:'PARCOURS';switcher.innerHTML=courses.map(c=>{const ready=Boolean(c.geojson||c.source),active=isVisible(c);return `<button class="route ${active?'active':''}" data-course-id="${esc(c.id)}" style="--route-color:${esc(c.color||'#315c4c')}" aria-pressed="${active}"><i class="dot"></i><span><strong>${esc(c.name)}</strong><small>${Number(c.distance).toLocaleString('fr-FR')} km${ready?'':' · trace à importer'}</small></span></button>`;}).join('')||`<p class="route-empty">Aucun parcours pour cette édition.${repo.admin?' Ajoutez-en un depuis Administration → Parcours.':''}</p>`;}
  function updateEditionOptions(){byId('editionSelect').innerHTML=state.editions.map(e=>`<option value="${esc(e.id)}">${esc(e.name)}</option>`).join('');byId('editionSelect').value=editionId;updateCourseOptions();}
  function isVisible(c){return visibility.has(c.id)?visibility.get(c.id):c.visible!==false;}
  async function getTrace(c){if(c.geojson)return c.geojson;if(!c.source)return null;if(!/^\.\/data\/routes\/\d+\.geojson$/.test(c.source))throw Error('Source de parcours non autorisée. Importez un GPX/KML.');if(!traces.has(c.source))traces.set(c.source,await fetchJsonRequired(c.source,`trace du parcours ${c.name}`));return traces.get(c.source);}
  function traceCoords(geojson){return (geojson?.type==='FeatureCollection'?geojson.features:[geojson]).flatMap(f=>f?.geometry?.type==='LineString'?f.geometry.coordinates:[]);}
